import re

def anti_shuffle(s):
    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            result.append(token)
        else:
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
    return ''.join(result)
